    posted_url: postedUrl || '',
    approval_token: '',
    error: '',
    updated_at: now.toISOString(),
  });
}

function publishFailure(row, error, now) {
  return sheetPatch(row, {
    status: 'Pending Approval',
    error: clip(error, 500),
    updated_at: now.toISOString(),
  });
}

