    warnings.push('X pe is tool ki approve ke baad caption jati hai. Image attach is version mein nahi hoti.');
  }
  if (platform === 'linkedin' && mediaKind !== 'none') {
    warnings.push('LinkedIn pe is version mein approved text post hota hai. Drive image automatically attach nahi hoti.');
  }
  if ((platform === 'instagram' || platform === 'facebook') && (mediaUrl || slides.length)) {
    warnings.push('Instagram aur Facebook tabhi media utha pate hain jab Drive file Anyone with the link pe ho.');
  }
  const blocking = [];
  warnings.forEach((warning) => {
    if (/nahi lagti|video file Drive|accept nahi karta|supported list|set nahi/.test(warning)) blocking.push(warning);
  });
  return { ok: blocking.length === 0, warnings, blocking };
}

function extractDriveId(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const fromPath = raw.match(/\/d\/([a-zA-Z0-9_-]+)/);
  if (fromPath) return fromPath[1];
  const fromQuery = raw.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (fromQuery) return fromQuery[1];
  if (/^[a-zA-Z0-9_-]{20,}$/.test(raw) && raw.indexOf('/') === -1 && raw.indexOf('.') === -1) return raw;
  return '';
}

function mediaKindFromMime(mimeType, name) {
  const mime = String(mimeType || '').toLowerCase();
  const file = String(name || '').toLowerCase();
  if (mime === 'application/vnd.google-apps.document' || mime.indexOf('text/') === 0) return 'document';
  if (mime.indexOf('image/') === 0) return 'image';
  if (mime.indexOf('video/') === 0) return 'video';
  if (/\.(png|jpe?g|webp|gif)$/.test(file)) return 'image';
  if (/\.(mp4|mov|m4v|webm)$/.test(file)) return 'video';
  return 'file';
}

function publicDriveUrl(fileId) {
  if (!fileId) return '';
  return 'https://drive.google.com/uc?export=download&id=' + fileId;
}

function parseKeyedDescription(description) {
  const fields = { caption: '', drive: '', niche: '', link: '', voice: '', language: '' };
  let current = '';
  String(description || '').replace(/\r/g, '').split('\n').forEach((line) => {
    const match = line.match(/^(drive|caption|niche|link|voice|language)\s*:\s*(.*)$/i);
    if (match) {
      current = match[1].toLowerCase();
      fields[current] = match[2].trim();
      return;
    }
    if (current) fields[current] = (fields[current] + '\n' + line).trim();
  });
  return fields;
}

function untrackedDriveFiles(files, rows) {
  const known = new Set();
  (rows || []).forEach((row) => {
    if (row.drive_file_id) known.add(String(row.drive_file_id));
    const fromUrl = extractDriveId(row.drive_url);
    if (fromUrl) known.add(fromUrl);
  });
  return (files || []).filter((file) => {
    if (!file || !file.id) return false;
    if (String(file.mimeType || '').indexOf('application/vnd.google-apps.folder') === 0) return false;
    return !known.has(file.id);
  });
}

const INPUT_FIELDS = ['scheduled_at', 'platform', 'topic', 'drive_file_id', 'drive_url', 'raw_caption', 'niche', 'cta_link'];
const LOCKED_STATUSES = new Set(['pending approval', 'publishing', 'approved', 'posted', 'declined']);

function emptyDraftFields() {
  return {
    approval_token: '',
    prepared_caption: '',
    prepared_hashtags: '',
    prepared_title: '',
    trend_notes: '',
    full_post_preview: '',
    media_public_url: '',
    media_kind: '',
    posted_url: '',
    error: '',
    warnings: '',
    can_publish: '',
    updated_at: '',
  };
}

function blankRow(partial) {
  return Object.assign({
    post_id: '',
    source: 'sheet',
    scheduled_at: '',
    platform: '',
    topic: '',
    drive_file_id: '',
    drive_url: '',
    source_link: '',
    raw_caption: '',
    niche: '',
    cta_link: '',
    language: '',
    brand_voice: '',
    status: 'Scheduled',
    ig_user_id: '',
    facebook_page_id: '',
    linkedin_author_urn: '',
    tiktok_privacy_level: '',
    publish_mode: '',
    meta_graph_version: '',
    notify_email: '',
  }, emptyDraftFields(), partial || {});
}

function statusKey(row) {
  return String((row && row.status) || '').trim().toLowerCase();
}

function inputsChanged(existing, next) {
  return INPUT_FIELDS.some((field) => String(existing[field] || '') !== String(next[field] || ''));
}

function eventToDrafts(event, timeZone) {
  const title = String(event.summary || '').trim();
  const match = title.match(/^([^|]+)\|\s*(.+)$/);
  const fields = parseKeyedDescription(event.description || '');
  const when = event.start && (event.start.dateTime || event.start.date) ? (event.start.dateTime || event.start.date) : '';
  let scheduledAt = '';
  if (event.start && event.start.date && !event.start.dateTime) {
    scheduledAt = event.start.date + ' 09:00';
  } else if (when) {
    const parsed = new Date(when);
    if (!Number.isNaN(parsed.getTime())) {
      const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false,
      }).formatToParts(parsed);
      const pick = (type) => parts.find((part) => part.type === type).value;
      let hour = pick('hour');
      if (hour === '24') hour = '00';
      scheduledAt = pick('year') + '-' + pick('month') + '-' + pick('day') + ' ' + hour + ':' + pick('minute');
    }
  }
  const driveRaw = fields.drive || '';
  const base = {
    source: 'calendar',
    scheduled_at: scheduledAt,
    topic: match ? match[2].trim() : title,
    drive_file_id: extractDriveId(driveRaw),
    drive_url: /^https?:\/\//i.test(driveRaw) ? driveRaw : '',
    raw_caption: fields.caption || '',
    niche: fields.niche || '',
    cta_link: fields.link || '',
    language: fields.language || '',
    brand_voice: fields.voice || '',
    source_link: event.htmlLink || '',
  };
  if (!match) {
    return [blankRow(Object.assign(base, {
      post_id: 'cal_' + event.id + '_invalid',
      platform: '',
      status: 'Failed',
      error: 'Calendar title "Platform | Topic" hona chahiye. Example: Instagram | Winter serum',
    }))];
  }
  const platforms = splitPlatforms(match[1]);
  if (!platforms.length) {
    return [blankRow(Object.assign(base, {
      post_id: 'cal_' + event.id + '_invalid',
      platform: match[1].trim(),
      status: 'Failed',
      error: 'Platform pehchana nahi gaya. Instagram, Facebook, LinkedIn, X, TikTok, YouTube use karein.',
    }))];
  }
  return platforms.map((platform) => blankRow(Object.assign({}, base, {
    post_id: 'cal_' + event.id + '_' + platform,
    platform,
    status: 'Scheduled',
  })));
}

function mergeCalendarRows(existingRows, events, timeZone) {
  const byId = new Map();
  (existingRows || []).forEach((row) => {
    if (row && row.post_id) byId.set(String(row.post_id), row);
  });
  const upserts = [];
  (events || []).forEach((event) => {
    if (!event || !event.id) return;
    eventToDrafts(event, timeZone).forEach((draft) => {
      const existing = byId.get(draft.post_id);
      if (existing && LOCKED_STATUSES.has(statusKey(existing))) return;
      if (existing && !inputsChanged(existing, draft) && statusKey(existing) === statusKey(draft)) return;
      const next = existing ? Object.assign({}, existing, draft) : draft;
      if (existing && inputsChanged(existing, draft)) {
        Object.assign(next, emptyDraftFields(), { status: draft.status, error: draft.error || '' });
      }
      upserts.push(next);
    });
  });
  return upserts;
}

function stampRow(row, config) {
  const next = Object.assign({}, row);
  next.notify_email = config.notifyEmail || next.notify_email || '';
  next.ig_user_id = config.igUserId || next.ig_user_id || '';
  next.facebook_page_id = config.facebookPageId || next.facebook_page_id || '';
  next.linkedin_author_urn = config.linkedinAuthorUrn || next.linkedin_author_urn || '';
  next.tiktok_privacy_level = config.tiktokPrivacyLevel || next.tiktok_privacy_level || 'SELF_ONLY';
  next.publish_mode = config.publishMode || next.publish_mode || 'on_approve';
  next.meta_graph_version = config.metaGraphVersion || next.meta_graph_version || 'v21.0';
  next.timezone = config.timezone || 'Asia/Karachi';
  next.brand_name = config.brandName || '';
  next.niche = next.niche || config.niche || '';
  next.language = next.language || config.language || 'Urdu + English';
  next.brand_voice = next.brand_voice || config.brandVoice || '';
  next.webhook_base_url = String(config.webhookBaseUrl || '').replace(/\/$/, '');
  return next;
}

function repairRows(rows, config, now) {
  const updates = [];
  (rows || []).forEach((row) => {
    if (!row || !row.post_id) return;
    const status = statusKey(row);
    if (status === 'preparing' && ageHours(row.updated_at, now) >= 2) {
      updates.push(Object.assign({}, row, {
        status: 'Scheduled',
        error: 'Preparation beech mein ruk gayi thi, dobara queue mein hai.',
        updated_at: now.toISOString(),
      }));
    }
    if (status === 'publishing' && ageHours(row.updated_at, now) >= 0.25) {
      updates.push(Object.assign({}, row, {
        status: 'Pending Approval',
        error: 'Publish beech mein ruk gaya. Approval email se dubara approve karein.',
        updated_at: now.toISOString(),
      }));
    }
    if (status === 'scheduled' && (!normalizePlatform(row.platform) || !parseScheduledAt(row.scheduled_at, config.timezone))) {
      updates.push(Object.assign({}, row, {
        status: 'Failed',
        error: !normalizePlatform(row.platform)
          ? 'Platform khali hai ya ghalat hai.'
          : 'scheduled_at "YYYY-MM-DD HH:mm" hona chahiye, timezone ' + (config.timezone || 'Asia/Karachi') + '.',
        updated_at: now.toISOString(),
      }));
    }
  });
  return updates;
}

function selectWork(rows, config, now) {
  const lookahead = Number(config.lookaheadHours || 2);
  const grace = Number(config.graceHours || 12);
  const windowStart = now.getTime() - grace * 36e5;
  const windowEnd = now.getTime() + lookahead * 36e5;
  const prepare = [];
  const publish = [];
  (rows || []).forEach((row) => {
    if (!row || !row.post_id) return;
    const status = statusKey(row);
    const when = parseScheduledAt(row.scheduled_at, config.timezone);
    if (!when) return;
    const time = when.getTime();
    if (status === 'scheduled' && time >= windowStart && time <= windowEnd) {
      prepare.push(stampRow(row, config));
    }
    if (status === 'approved' && String(row.can_publish) === 'yes' && String(row.publish_mode || config.publishMode) === 'at_scheduled_time' && time <= now.getTime()) {
      publish.push(stampRow(row, config));
    }
  });
  return { prepare, publish };
}

function buildSystemPrompt() {
  return [
    'You prepare one social post from source material the user already wrote.',
    'Return only a JSON object with keys caption, hashtags, title, trend_notes, warnings.',
