}

function fitDraft(row, model) {
  const platform = normalizePlatform(row.platform);
  const spec = PLATFORMS[platform];
  const warnings = [];
  if (!spec) {
    return { ok: false, error: 'Platform supported nahi hai.', warnings };
  }
  const payload = model && typeof model === 'object' ? model : {};
  let caption = stripHashtags(payload.caption || '');
  const urlPass = stripUnknownUrls(caption, row);
  caption = urlPass.text;
  if (urlPass.removed.length) warnings.push('Jo links source mein nahi thay, nikaal diye gaye.');
  if (row.cta_link && caption.indexOf(String(row.cta_link).trim()) === -1) {
    caption = (caption + '\n\n' + String(row.cta_link).trim()).trim();
  }
  const tagPass = cleanTags(payload.hashtags, spec.hashtags);
  if (tagPass.droppedSpam.length) warnings.push('Fake engagement hashtags hata diye gaye.');
  if (tagPass.droppedExtra.length) warnings.push('Platform ki had se zyada hashtags hata diye gaye.');
  const genericCount = tagPass.tags.filter((tag) => GENERIC_TAGS.has(tag.toLowerCase())).length;
  if (tagPass.tags.length && genericCount * 2 > tagPass.tags.length) {
    warnings.push('Zyada tar hashtags bohot aam hain. Niche wale tags behtar hote hain.');
  }
  const notes = Array.isArray(payload.trend_notes) ? payload.trend_notes : [];
  const trendNotes = [];
  const kept = new Set(tagPass.tags.map((tag) => tag.toLowerCase()));
  notes.forEach((note) => {
    const tag = cleanTag(note && note.tag);
    if (!tag || !kept.has(tag.toLowerCase())) return;
    const kind = String(note.kind || '').toLowerCase() === 'timely' ? 'timely' : 'evergreen';
    const why = clip(note.why || '', 180);
    if (/viral|guaranteed|million views|%\s*growth/i.test(why)) {
      warnings.push(tag + ' ki timing claim hata di gayi kyunke us mein number ya viral claim tha.');
      trendNotes.push({ tag, kind: 'evergreen', why: 'Source ne is tag ko topic se mutabiq rakha hai.' });
      return;
    }
    trendNotes.push({ tag, kind, why: why || 'Is topic ke audiences yeh tag pehle se use karte hain.' });
  });
  tagPass.tags.forEach((tag) => {
    if (!trendNotes.some((note) => note.tag.toLowerCase() === tag.toLowerCase())) {
      trendNotes.push({ tag, kind: 'evergreen', why: 'Model ne is tag ki timing confirm nahi ki, is liye evergreen rakha gaya.' });
    }
  });
  let title = clip(payload.title || row.topic || '', spec.title || 100);
  const hashtagLine = tagPass.tags.join(' ');
  let full = caption;
  if (platform !== 'youtube' && hashtagLine) full = (caption + '\n\n' + hashtagLine).trim();
  if (platform === 'x' && full.length > spec.caption) {
    const room = spec.caption - (hashtagLine ? hashtagLine.length + 2 : 0);
    if (room < 20) {
      full = clip(caption, spec.caption);
      warnings.push('X ki 280 limit ki wajah se hashtags nahi aaye.');
    } else {
      const trimmed = clip(caption, room).replace(/\s+\S*$/, '').trim();
      full = hashtagLine ? trimmed + '\n\n' + hashtagLine : trimmed;
      warnings.push('X ki 280 limit ki wajah se caption chhota kiya gaya. Jo text neeche hai wahi post hoga.');
    }
    if (full.length > spec.caption) full = clip(full, spec.caption);
  }
  if (platform !== 'x' && full.length > spec.caption) {
    full = clip(full, spec.caption);
    warnings.push('Caption platform limit se lamba tha, limit tak chhota kiya gaya.');
  }
  if (!caption) return { ok: false, error: 'AI ne khali caption diya.', warnings };
  const media = canPublish(row);
  media.warnings.forEach((warning) => warnings.push(warning));
  let preview = full;
  if (platform === 'youtube') {
    preview = 'TITLE:\n' + title + '\n\nDESCRIPTION:\n' + caption + '\n\nTAGS:\n' + tagPass.tags.map((tag) => tag.replace(/^#/, '')).join(', ');
  }
  return {
    ok: true,
    prepared_caption: platform === 'youtube' ? caption : full,
    prepared_hashtags: platform === 'youtube' ? tagPass.tags.map((tag) => tag.replace(/^#/, '')).join(', ') : hashtagLine,
    prepared_title: platform === 'youtube' ? title : '',
    trend_notes: JSON.stringify(trendNotes),
    full_post_preview: preview,
    publish_text: platform === 'youtube' ? caption : full,
    warnings: warnings.join('\n'),
    can_publish: media.ok ? 'yes' : 'no',
    error: media.ok ? '' : media.blocking.join(' '),
  };
}

function parseModelContent(content) {
  const parsed = JSON.parse(stripFences(content));
  if (parsed && parsed.post && typeof parsed.post === 'object') return parsed.post;
  return parsed;
}

function reviewUrl(row) {
  const base = String(row.webhook_base_url || '').replace(/\/$/, '');
  const local = /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/i.test(base);
  if (!/^https:\/\//i.test(base) && !local) return '';
  return base + '/webhook/post-review?post_id=' + encodeURIComponent(row.post_id) + '&token=' + encodeURIComponent(row.approval_token || '');
}

function pageShell(title, body) {
  return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'
    + escapeHtml(title) + '</title></head><body style="margin:0;background:#f4f1ea;color:#1c1917;font-family:Georgia,serif;">'
    + '<main style="max-width:680px;margin:0 auto;padding:28px 18px;">' + body + '</main></body></html>';
}

function renderResultPage(title, message) {
  return pageShell(title, '<h1 style="font-size:28px;line-height:1.2;">' + escapeHtml(title) + '</h1><p style="font-size:18px;line-height:1.5;">' + escapeHtml(message) + '</p>');
}

function renderTrendNotes(raw) {
  let notes = [];
  try { notes = JSON.parse(raw || '[]'); } catch (error) { notes = []; }
  if (!Array.isArray(notes) || !notes.length) return '<p>Hashtag ki timing note maujood nahi.</p>';
  return '<ul>' + notes.map((note) => '<li><strong>' + escapeHtml(note.tag) + '</strong> · ' + escapeHtml(note.kind) + ' — ' + escapeHtml(note.why) + '</li>').join('') + '</ul>';
}

function mediaLinks(row) {
  const urls = String(row.media_urls || '').split(/\s+/).map((url) => url.trim()).filter((url) => /^https:\/\//i.test(url));
  if (urls.length > 1) {
    return '<ol>' + urls.map((url, index) => '<li><a href="' + escapeHtml(url) + '">Slide ' + (index + 1) + '</a></li>').join('') + '</ol>';
  }
  if (row.media_public_url) return '<p><a href="' + escapeHtml(row.media_public_url) + '">Media dekhein</a></p>';
  return '';
}

function renderReviewPage(row, decisionUrl) {
  const when = formatInZone(parseScheduledAt(row.scheduled_at, row.timezone), row.timezone);
  const modeNote = row.publish_mode === 'at_scheduled_time'
    ? 'Approve ke baad post scheduled time se pehle nahi lagegi.'
    : 'Approve karte hi post usi waqt live ho jayegi.';
  const blocked = String(row.can_publish) !== 'yes';
  const approve = blocked
    ? '<p style="background:#fff4e5;padding:12px;">Approve band hai. Pehle warning theek karein, phir sheet mein status Scheduled kar ke naya draft banwayein.</p>'
    : '<form method="POST" action="' + escapeHtml(decisionUrl) + '">'
      + hiddenFields(row, 'approve')
      + '<button style="background:#0f7b4c;color:white;border:0;padding:14px 18px;font-size:16px;cursor:pointer;" type="submit">Approve karo, post lagao</button></form>';
  const decline = '<form method="POST" action="' + escapeHtml(decisionUrl) + '" style="margin-top:10px;">'
    + hiddenFields(row, 'decline')
    + '<button style="background:#9b2c2c;color:white;border:0;padding:14px 18px;font-size:16px;cursor:pointer;" type="submit">Decline karo, post mat lagao</button></form>';
  const body = '<p style="letter-spacing:.08em;text-transform:uppercase;font-size:12px;">Approval</p>'
    + '<h1 style="font-size:32px;line-height:1.15;margin-bottom:8px;">' + escapeHtml((PLATFORMS[normalizePlatform(row.platform)] || {}).label || row.platform || 'Post') + '</h1>'
    + '<p>' + escapeHtml(modeNote) + '</p>'
    + '<p><strong>Waqt:</strong> ' + escapeHtml(when || row.scheduled_at) + '<br><strong>Topic:</strong> ' + escapeHtml(row.topic || '') + '</p>'
    + mediaLinks(row)
    + '<h2>Yeh exact post lagegi</h2><pre style="white-space:pre-wrap;background:white;padding:16px;border:1px solid #e7e5e4;">' + escapeHtml(row.full_post_preview || '') + '</pre>'
    + '<h2>Hashtags kyun</h2>' + renderTrendNotes(row.trend_notes)
    + (row.warnings ? '<h2>Warnings</h2><pre style="white-space:pre-wrap;background:#fff7ed;padding:16px;">' + escapeHtml(row.warnings) + '</pre>' : '')
    + approve + decline;
  return pageShell('Post approval', body);
}

function hiddenFields(row, action) {
  return '<input type="hidden" name="post_id" value="' + escapeHtml(row.post_id) + '">'
    + '<input type="hidden" name="token" value="' + escapeHtml(row.approval_token) + '">'
