  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: timeZone || 'UTC',
    hour: '2-digit',
    hour12: false,
  }).formatToParts(date);
  let hour = parts.find((part) => part.type === 'hour').value;
  if (hour === '24') hour = '0';
  return Number(hour);
}

function dayKeyInZone(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: timeZone || 'UTC',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const pick = (type) => parts.find((part) => part.type === type).value;
  return pick('year') + '-' + pick('month') + '-' + pick('day');
}

function zoneOffsetMs(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour12: false,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  }).formatToParts(date);
  const pick = (type) => parts.find((part) => part.type === type).value;
  let hour = pick('hour');
  if (hour === '24') hour = '0';
  const asUtc = Date.UTC(Number(pick('year')), Number(pick('month')) - 1, Number(pick('day')), Number(hour), Number(pick('minute')), Number(pick('second')));
  return asUtc - date.getTime();
}

function zonedTimeToUtc(year, month, day, hour, minute, timeZone) {
  let guess = new Date(Date.UTC(year, month - 1, day, hour, minute, 0));
  for (let i = 0; i < 3; i += 1) {
    const offset = zoneOffsetMs(guess, timeZone);
    guess = new Date(Date.UTC(year, month - 1, day, hour, minute, 0) - offset);
  }
  return guess;
}

function parseScheduledAt(value, timeZone) {
  const raw = String(value || '').trim();
